cd /workspace && python3 - <<'PY'
import sys,string;sys.path.insert(0,'submission');import gateway
allowed=string.ascii_letters+string.digits+"-_.!~*'()+"
bad=''.join(c for c in string.printable if c not in allowed and c not in '\t\n\r\x0b\x0c')
print('bad chars test')
for c in allowed:
 try: gateway.parse_uri('sip:'+c+'@h')
 except Exception as e: print('underaccept raw',repr(c))
for c in bad:
 try:
  gateway.parse_uri('sip:a'+c+'b@h'); print('overaccept raw',repr(c))
 except gateway.SIPFailure: pass
# escape all allowed
for c in allowed:
 try: gateway.parse_uri('sip:%'+format(ord(c),'02x')+'@h')
 except Exception: print('underaccept esc',repr(c))
for c in set(string.printable)-set(allowed):
 if c in '\t\n\r\x0b\x0c': continue
 try:
  gateway.parse_uri('sip:%'+format(ord(c),'02x')+'@h'); print('overaccept esc',repr(c))
 except gateway.SIPFailure: pass
PY
